{"name":"loadConfigDiagnostics","qualified_name":"Users-appointy-Documents-New-project-6.internal.taskpilot.cli.loadConfigDiagnostics","label":"Function","file_path":"/Users/appointy/Documents/New project 6/internal/taskpilot/cli.go","start_line":8843,"end_line":8886,"source":"func loadConfigDiagnostics(effective bool) (configDiagnostics, error) {
	fileCfg, err := loadConfigFile()
	if err != nil {
		return configDiagnostics{}, err
	}
	cfg := fileCfg
	sources := map[string]string{
		"server":       "file",
		"email":        "file",
		"actor_id":     "file",
		"actor_secret": "file",
	}
	envOverrideActive := false
	if effective {
		if strings.TrimSpace(os.Getenv("TASKPILOT_SERVER")) != "" {
			sources["server"] = "env:TASKPILOT_SERVER"
			envOverrideActive = true
		}
		if strings.TrimSpace(os.Getenv("TASKPILOT_ACTOR_ID")) != "" {
			sources["actor_id"] = "env:TASKPILOT_ACTOR_ID"
			envOverrideActive = true
		}
		if strings.TrimSpace(os.Getenv("TASKPILOT_ACTOR_SECRET")) != "" {
			sources["actor_secret"] = "env:TASKPILOT_ACTOR_SECRET"
			envOverrideActive = true
		}
		cfg = applyConfigEnvOverrides(fileCfg)
	}
	auth := "actor_secret"
	if cfg.ActorID == "" || cfg.ActorSecret == "" {
		auth = "not_configured"
	}
	return configDiagnostics{
		ConfigPath:        configPath(),
		Server:            cfg.Server,
		Email:             cfg.Email,
		ActorID:           cfg.ActorID,
		HasSecret:         cfg.ActorSecret != "",
		Auth:              auth,
		Sources:           sources,
		Effective:         effective,
		EnvOverrideActive: envOverrideActive,
	}, nil
}
