{"name":"heartbeatLoop","qualified_name":"Users-appointy-Documents-New-project-6.internal.taskpilot.cli.heartbeatLoop","label":"Function","file_path":"/Users/appointy/Documents/New project 6/internal/taskpilot/cli.go","start_line":3357,"end_line":3371,"source":"func heartbeatLoop(ctx context.Context, taskID string, done <-chan struct{}) {
	ticker := time.NewTicker(heartbeatInterval())
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-done:
			return
		case <-ticker.C:
			var out Task
			_ = request("POST", "/api/tasks/"+taskID+"/heartbeat", map[string]any{}, &out)
		}
	}
}
