{"name":"runLock","qualified_name":"Users-appointy-Documents-New-project-6.internal.taskpilot.cli.runLock","label":"Function","file_path":"/Users/appointy/Documents/New project 6/internal/taskpilot/cli.go","start_line":8392,"end_line":8425,"source":"func runLock(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("usage: taskpilot lock acquire|release|renew")
