	_ = s.markStaleLocks(ctx, time.Now().UTC())
	conflicts, err := s.FindLockConflicts(ctx, actorID, scope, scopeType)
	if err != nil {
		return Lock{}, nil, err
	}
	if len(conflicts) > 0 {
